JSON_TEST(allow_hexadecimal_numbers, bad_hexadecimal_char) {
  const char payload[] = "{\"foo\" : 0xA012aBbDEF8976cCdef453g}";
  struct json_parse_result_s result;
  struct json_value_s *value = json_parse_ex(
      payload, strlen(payload), json_parse_flags_allow_hexadecimal_numbers,
      UTEST_NULL, UTEST_NULL, &result);
  ASSERT_FALSE(value);
  ASSERT_EQ(json_parse_error_invalid_number_format, result.error);
  ASSERT_EQ(33u, result.error_offset);
  ASSERT_EQ(1u, result.error_line_no);
  ASSERT_EQ(33u, result.error_row_no);
}

