JSON_TEST(object, missing_closing_bracket) {
  const char payload[] = "{\n  \"dps\":[1, 2, {\"a\" : true]\n}";

  struct json_parse_result_s result;

  struct json_value_s *value = json_parse_ex(
      payload, strlen(payload), UTEST_NULL, UTEST_NULL, UTEST_NULL, &result);

  ASSERT_FALSE(value);

  ASSERT_EQ(json_parse_error_expected_comma_or_closing_bracket, result.error);
  ASSERT_EQ(28u, result.error_offset);
  ASSERT_EQ(2u, result.error_line_no);
  ASSERT_EQ(27u, result.error_row_no);
}

