#define JSONTESTSUITE_TESTS (340)

JSON_TEST(JSONTestSuiteTests, all) {
  size_t utest_index;

  for (utest_index = 0; utest_index < JSONTESTSUITE_TESTS; ++utest_index) {
    const unsigned char *string = JSONTestSuite[utest_index].string;
    size_t length = JSONTestSuite[utest_index].length;
    ExpectedResult expected = JSONTestSuite[utest_index].expected;
    int skip = 0;
    struct json_value_s *value;

    switch (utest_index) {
    default:
      break;
    case 174:
      // 100,000 array openings
    case 200:
      // tons of open array objects
      skip = 1;
      break;
    case 333:
      // High continuation with no follow-up
    case 335:
      // Two high continuations
    case 337:
      // Three high continuations
      expected = ExpectedResultFail;
      break;
    }

    if (skip) {
      continue;
    }

    value = json_parse(string, length);

#if defined(__clang__)
#pragma clang diagnostic push
#pragma clang diagnostic ignored "-Wcovered-switch-default"
#endif
    switch (expected) {
    default:
    case ExpectedResultPass:
      ASSERT_TRUE(value);
      break;
    case ExpectedResultFail:
      ASSERT_FALSE(value);
      break;
    case ExpectedResultUndefined:
      break;
    }
#if defined(__clang__)
#pragma clang diagnostic pop
#endif

    free(value);
  }
}

#if defined(__clang__)
#pragma clang diagnostic pop
#endif
